# /// script
# requires-python = ">=3.12"
# dependencies = ["playwright"]
# ///
import sys
from pathlib import Path
from playwright.sync_api import sync_playwright

REPO = Path("/Users/sweetjp/DEV/git_repos/minecraft-mods/ModularPlanters")
OUT = REPO / "wiki/assets/modular_planters/builds"
BUILDS = {"raised_bed": "raisedBed", "vertical_farm": "verticalFarm", "rosette": "rosette"}

OUT.mkdir(parents=True, exist_ok=True)
with sync_playwright() as p:
    browser = p.chromium.launch(args=["--use-angle=swiftshader", "--enable-unsafe-swiftshader", "--ignore-gpu-blocklist"])
    page = browser.new_page(viewport={"width": 1400, "height": 1000})
    page.on("console", lambda m: print("console:", m.text, file=sys.stderr))
    page.on("pageerror", lambda e: print("pageerror:", e, file=sys.stderr))
    page.goto((REPO / "mockups/layouts.html").as_uri(), wait_until="networkidle")
    page.wait_for_timeout(3000)
    for name, layout in BUILDS.items():
        el = page.locator(f'canvas[data-layout="{layout}"]')
        el.scroll_into_view_if_needed()
        page.wait_for_timeout(500)
        el.screenshot(path=str(OUT / f"{name}.png"))
        print("saved", name)
    browser.close()
